#[derive(Debug, Clone, Copy)]
pub struct TranscodingFailures;

impl TranscodingFailures {
    /// The failure `REFUSED`, code 1.
    pub const REFUSED: ::bead::ListedFailure = ::bead::ListedFailure::new(
        "REFUSED",
        ::core::num::NonZeroU16::new(1).expect("a failure's code, from 1 to 65,535 (spec 9.5)"),
    );

    /// The failure `COUNTED`, code 2.
    pub const COUNTED: ::bead::ListedFailure = ::bead::ListedFailure::new(
        "COUNTED",
        ::core::num::NonZeroU16::new(2).expect("a failure's code, from 1 to 65,535 (spec 9.5)"),
    );

    /// The catalogue of service 1, every failure of it, made once a process.
    ///
    /// # Errors
    ///
    /// A [`ProgrammerError`](::bead::ProgrammerError) where the runtime refuses the catalogue.
    pub fn catalogue() -> Result<&'static ::bead::FailureCatalogue, ::bead::ProgrammerError> {
        static CATALOGUE: ::std::sync::LazyLock<Result<::bead::FailureCatalogue, ::bead::ProgrammerError>> =
            ::std::sync::LazyLock::new(|| {
                ::bead::failures_of(1, &[TranscodingFailures::REFUSED, TranscodingFailures::COUNTED])
            });

        CATALOGUE.as_ref().map_err(::core::clone::Clone::clone)
    }

    /// Whether `error` is `failure`, answered by a procedure of this service.
    #[must_use]
    pub fn is(error: &::bead::CallError, failure: &::bead::ListedFailure) -> bool {
        Self::catalogue().is_ok_and(|catalogue| catalogue.is(error, failure))
    }
}

