/// The client side of `bead.transcoding.v1.TranscodingService`, over one Bead client: a requester of each procedure its server answers, by its name.
#[derive(Debug, Clone)]
pub struct TranscodingClient {
    procedures: &'static TranscodingProcedures,
    service: ::bead::ServiceClient,
    request: TranscodingRequesters,
    notifications: TranscodingNotifications,
}

impl TranscodingClient {
    /// The client side of `bead.transcoding.v1.TranscodingService`, over `client`, given its options: whether it validates, and the windows of its notifications.
    ///
    /// # Errors
    ///
    /// A [`ProgrammerError`](::bead::ProgrammerError) where the runtime refuses the service; for a window of 0, a second client side over one client at another window, or a procedure its router refuses to declare.
    pub fn new(client: &::bead::Client, options: &TranscodingClientOptions) -> Result<Self, ::bead::ProgrammerError> {
        let procedures = TranscodingProcedures::get()?;
        let mut layer = ::bead::ServiceClientOptions::default();

        let windows = options.windows.clone().unwrap_or_default();
        let mut given = ::std::collections::BTreeMap::new();

        if let Some(window) = windows.ticks {
            given.insert("ticks".to_owned(), window);
        }

        if let Some(window) = windows.watch {
            given.insert("watch".to_owned(), window);
        }

        layer.windows = Some(given);
        layer.fail_fast = options.fail_fast;
        layer.validates = options.validates;

        let service = ::bead::ServiceClient::new(procedures.all(), client, &layer)?;
        let request = TranscodingRequesters {
            echo: service.requester_of(&procedures.echo)?,
            echo_edges: service.requester_of(&procedures.echo_edges)?,
            get_book: service.requester_of(&procedures.get_book)?,
            list_books: service.requester_of(&procedures.list_books)?,
            update_book: service.requester_of(&procedures.update_book)?,
            archive_book: service.requester_of(&procedures.archive_book)?,
            list_operations: service.requester_of(&procedures.list_operations)?,
            get_operation: service.requester_of(&procedures.get_operation)?,
            judge: service.requester_of(&procedures.judge)?,
            ticks: service.requester_of(procedures.ticks.descriptor())?,
            watch: service.requester_of(procedures.watch.descriptor())?,
            raw: service.requester_of(&procedures.raw)?,
            text: service.requester_of(&procedures.text)?,
            json: service.requester_of(&procedures.json)?,
            fail: service.requester_of(&procedures.fail)?,
            who_am_i: service.requester_of(&procedures.who_am_i)?,
            ask: service.requester_of(&procedures.ask)?,
            hang: service.requester_of(&procedures.hang)?,
            cancels: service.requester_of(&procedures.cancels)?,
            require: service.requester_of(&procedures.require)?,
            get_needs: service.requester_of(&procedures.get_needs)?,
            update_needs: service.requester_of(&procedures.update_needs)?,
        };
        let notifications = TranscodingNotifications {
            ticks: service.notification_of(&procedures.ticks)?,
            watch: service.notification_of(&procedures.watch)?,
        };

        Ok(Self {
            procedures,
            service,
            request,
            notifications,
        })
    }

    /// The requester of each procedure its server answers, by its name.
    #[must_use]
    pub const fn request(&self) -> &TranscodingRequesters {
        &self.request
    }

    /// The notification of each procedure that notifies, at the window its options gave, or unpaced.
    #[must_use]
    pub const fn notifications(&self) -> &TranscodingNotifications {
        &self.notifications
    }

    /// Registers the resolver of the command `answer`, which it answers.
    ///
    /// # Errors
    ///
    /// A [`ProgrammerError`](::bead::ProgrammerError) for a resolver registered already, or one its router refuses.
    pub fn on_answer<F, Fut>(&self, resolver: F) -> Result<(), ::bead::ProgrammerError>
    where
        F: Fn(
                ::bead::RequestProps<::buffa_types::google::protobuf::Empty>,
                ::bead::Response<::bead_protobuf::ProtoCodec<::buffa_types::google::protobuf::Empty>>,
            ) -> Fut
            + Send
            + Sync
            + 'static,
        Fut: ::core::future::Future<Output = Result<(), ::bead::ResolverError>> + Send + 'static,
    {
        self.service.on(
            &self.procedures.answer,
            ::std::sync::Arc::new(move |request, response| ::std::boxed::Box::pin(resolver(request, response))),
        )
    }
}

// * each request's rules, judged before its resolver, every rule a site of its own (spec 18,
// decision 0035)

const RULED_FROM_INT32_LTE: ::bead_protobuf::ViolationRule = ::bead_protobuf::ViolationRule {
    rule_id: "int32.lte",
    message: "must be less than or equal to 10",
    bounds: Some("{\"lte\":10}"),
    for_key: false,
};

const RULED_TITLE_STRING_MAX_LEN: ::bead_protobuf::ViolationRule = ::bead_protobuf::ViolationRule {
    rule_id: "string.max_len",
    message: "must be at most 3 characters",
    bounds: Some("{\"max_len\":\"3\"}"),
    for_key: false,
};

// the rules of `bead.transcoding.v1.Ruled`, in spec 18.5's order: `true` where the judging stops
fn rules_of_ruled(message: &super::super::super::super::messages::bead::transcoding::v1::Ruled, sink: &mut dyn ::bead_protobuf::ViolationSink) -> bool {
    rules_of_ruled_from(message, sink)
        || rules_of_ruled_title(message, sink)
}

// from, 1
fn rules_of_ruled_from(message: &super::super::super::super::messages::bead::transcoding::v1::Ruled, sink: &mut dyn ::bead_protobuf::ViolationSink) -> bool {
    let value = &message.from;

    sink.enter("from");

    if !value.partial_cmp(&10).is_some_and(::core::cmp::Ordering::is_le)
        && sink.add(&RULED_FROM_INT32_LTE, ::bead_protobuf::RuleValue::Signed(i64::from(*value)))
    {
        return true;
    }

    sink.leave();

    false
}

// title, 2
fn rules_of_ruled_title(message: &super::super::super::super::messages::bead::transcoding::v1::Ruled, sink: &mut dyn ::bead_protobuf::ViolationSink) -> bool {
    let value = &message.title;

    sink.enter("title");

    if ::bead_protobuf::code_point_length(value) > 3
        && sink.add(&RULED_TITLE_STRING_MAX_LEN, ::bead_protobuf::RuleValue::Text(value))
    {
        return true;
    }

    sink.leave();

    false
}

